    private function save_opts(){check_admin_referer('xdn_save_settings');update_option(self::OPT_KEY,['api_key'=>trim(sanitize_text_field(wp_unslash($_POST['api_key']??''))),'model'=>sanitize_text_field(wp_unslash($_POST['model']??'gpt-5-mini')),'default_category'=>absint($_POST['default_category']??0),'internal_links'=>!empty($_POST['internal_links'])?1:0,'specs_section'=>!empty($_POST['specs_section'])?1:0,'max_internal_links'=>max(0,min(6,absint($_POST['max_internal_links']??3)))]);}
