<script>(function(){const ajax='<?php echo esc_js(admin_url('admin-ajax.php'));?>',nonce='<?php echo esc_js(wp_create_nonce(self::NONCE));?>',R=document.getElementById('xdn_results'),S=document.getElementById('xdn_status');const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));document.getElementById('xdn_scan').onclick=async function(){const u=document.getElementById('xdn_source_url').value.trim();if(!u){S.innerHTML='Nhập URL nguồn.';return}this.disabled=true;S.innerHTML='Đang quét...';const f=new FormData();f.append('action','xdn_scan_source');f.append('nonce',nonce);f.append('source_url',u);f.append('scan_all',document.getElementById('xdn_scan_all').checked?'1':'0');try{const j=await(await fetch(ajax,{method:'POST',body:f})).json();if(!j.success)throw Error(j.data||'Lỗi');render(j.data.products||[],j.data.pages||[]);S.innerHTML='Đã tìm thấy <b>'+(j.data.products||[]).length+'</b> sản phẩm trên <b>'+(j.data.pages||[]).length+'</b> trang.'}catch(e){S.innerHTML='<span class="xdn-error">'+esc(e.message)+'</span>'}this.disabled=false};function render(ps,pages){if(!ps.length){R.innerHTML='<p class="xdn-error">Không tìm thấy sản phẩm.</p>';return}let h='<div style="margin-bottom:10px"><button class="button" id="all">Chọn tất cả</button> <button class="button" id="none">Bỏ chọn</button> <select id="cat"><option value="0">Danh mục WooCommerce...</option><?php foreach($cats as $cat)echo '<option value="'.esc_attr($cat->term_id).'">'.esc_html($cat->name).'</option>';?></select> <label><input id="ai" type="checkbox" checked> GPT viết lại SEO</label> <button class="button button-primary" id="imp">Nhập sản phẩm đã chọn</button></div><p>Trang: '+pages.map(p=>'<a target="_blank" href="'+esc(p.url)+'">'+esc(p.label)+'</a>').join(' · ')+'</p><table><thead><tr><th><input id="master" type="checkbox"></th><th>Ảnh</th><th>Sản phẩm nguồn</th><th>Giá</th><th>Loại</th><th>Trạng thái</th></tr></thead><tbody>';ps.forEach(p=>{h+='<tr><td><input class="item" type="checkbox" checked data-json=\''+esc(JSON.stringify(p))+'\'></td><td>'+(p.image?'<img src="'+esc(p.image)+'">':'')+'</td><td><b>'+esc(p.name)+'</b><br><a target="_blank" href="'+esc(p.url)+'">Mở nguồn</a></td><td>'+esc(p.price||'—')+'</td><td><span class="xdn-pill">'+(p.has_variations?'Có tùy chọn/biến thể':'Sản phẩm thường')+'</span></td><td class="st">Chờ nhập</td></tr>'});h+='</tbody></table><div id="log" class="xdn-log" style="display:none"></div>';R.innerHTML=h;document.getElementById('all').onclick=()=>document.querySelectorAll('.item').forEach(x=>x.checked=true);document.getElementById('none').onclick=()=>document.querySelectorAll('.item').forEach(x=>x.checked=false);document.getElementById('master').onchange=e=>document.querySelectorAll('.item').forEach(x=>x.checked=e.target.checked);document.getElementById('imp').onclick=importSelected}async function importSelected(){const items=[...document.querySelectorAll('.item:checked')];if(!items.length)return alert('Chưa chọn sản phẩm.');const fcat=document.getElementById('cat').value||<?php echo (int)$o['default_category'];?>,useAI=document.getElementById('ai').checked?'1':'0',log=document.getElementById('log'),btn=document.getElementById('imp'),counter=document.getElementById('xdn_import_counter');let success=0,skipped=0,failed=0;const total=items.length;const updateCounter=()=>{counter.innerHTML='<div class="xdn-summary"><span class="xdn-ok">Đã nhập thành công: <strong>'+success+'</strong></span><span>Đang xử lý: <strong>'+Math.max(0,total-success-skipped-failed)+'</strong></span><span class="xdn-skip">Đã bỏ qua: <strong>'+skipped+'</strong></span><span class="xdn-error">Lỗi: <strong>'+failed+'</strong></span><span>Tổng chọn: <strong>'+total+'</strong></span></div>';};updateCounter();log.style.display='block';btn.disabled=true;for(const it of items){const p=JSON.parse(it.dataset.json),fd=new FormData(),row=it.closest('tr'),st=row.querySelector('.st');st.textContent='Đang nhập...';fd.append('action','xdn_import_products');fd.append('nonce',nonce);fd.append('products',JSON.stringify([p]));fd.append('category',fcat);fd.append('use_ai',useAI);try{const j=await(await fetch(ajax,{method:'POST',body:fd})).json();if(!j.success)throw Error(j.data||'Lỗi');const x=j.data.results[0];if(x.status==='created'){success++;st.innerHTML='<span class="xdn-ok">Đã tạo #'+x.id+'</span>'}else if(x.status==='exists'){skipped++;st.innerHTML='<span class="xdn-skip">Đã tồn tại #'+x.id+'</span><span class="xdn-status-note">'+esc(x.message||'Sản phẩm đã tồn tại')+'</span> <a class="button button-small xdn-action" target="_blank" href="'+esc(x.edit_url||'#')+'">Xem sản phẩm</a> <button type="button" class="button button-small xdn-action xdn-update-source" data-id="'+esc(x.id)+'" data-url="'+esc(p.url)+'">Cập nhật từ nguồn</button>'}else{skipped++;st.innerHTML='<span class="xdn-skip">Bỏ qua</span><span class="xdn-status-note">'+esc(x.message||'Không nhập')+'</span>'}log.innerHTML+=esc(p.name)+' → '+esc(x.message||'')+'<br>'}catch(e){failed++;st.innerHTML='<span class="xdn-error">Lỗi: '+esc(e.message)+'</span>';log.innerHTML+=esc(p.name)+' → '+esc(e.message)+'<br>'}updateCounter();}btn.disabled=false;updateCounter()}
R.onclick=async function(e){const b=e.target.closest('.xdn-update-source');if(!b)return;const id=b.dataset.id,url=b.dataset.url;if(!id||!url)return;b.disabled=true;b.textContent='Đang cập nhật...';const fd=new FormData();fd.append('action','xdn_update_source');fd.append('nonce',nonce);fd.append('product_id',id);fd.append('source_url',url);fd.append('use_ai',document.getElementById('ai')?.checked?'1':'0');try{const j=await(await fetch(ajax,{method:'POST',body:fd})).json();if(!j.success)throw Error(j.data||'Lỗi');b.outerHTML='<span class="xdn-ok">Đã cập nhật #'+esc(id)+'</span>';const l=document.getElementById('log');if(l)l.innerHTML+='Cập nhật #'+esc(id)+' → '+esc(j.data?.message||'Đã cập nhật')+'<br>';}catch(err){b.disabled=false;b.textContent='Cập nhật từ nguồn';alert('Không cập nhật được: '+err.message)}};}})();</script>
<?php }

    private function get_html($url){$r=wp_remote_get($url,['timeout'=>25,'redirection'=>5,'user-agent'=>'XE-DAP-NINH-BINH-Importer/2.2','headers'=>['Accept'=>'text/html,application/xhtml+xml','Accept-Language'=>'vi,en;q=0.8']]);if(is_wp_error($r))return $r;$c=wp_remote_retrieve_response_code($r);if($c<200||$c>=400)return new WP_Error('http_error','Nguồn trả HTTP '.$c);return wp_remote_retrieve_body($r);}
    private function abs_url($url,$base){if(!$url)return '';$url=trim(html_entity_decode($url));if(preg_match('#^https?://#i',$url))return $url;if(strpos($url,'//')===0)return 'https:'.$url;$p=wp_parse_url($base);if(!$p||empty($p['scheme'])||empty($p['host']))return $url;if($url[0]==='/')return $p['scheme'].'://'.$p['host'].$url;$path=$p['path']??'/';return $p['scheme'].'://'.$p['host'].trailingslashit(dirname($path)).$url;}
    private function normalize_url($url){$url=strtok($url,'#');return trailingslashit($url);}
    private function dom($html){if(!class_exists('DOMDocument'))return false;libxml_use_internal_errors(true);$d=new DOMDocument();@$d->loadHTML('<?xml encoding="utf-8" ?>'.$html);libxml_clear_errors();return $d;}
    private function clean_text($s){$s=html_entity_decode(wp_strip_all_tags((string)$s),ENT_QUOTES,'UTF-8');$s=preg_replace('/\s+/u',' ',trim($s));return $s;}
    private function xpath_text($xp,$queries){foreach($queries as $q){$n=@$xp->query($q);if($n&&$n->length){$v=$this->clean_text($n->item(0)->textContent);if($v)return $v;}}return '';}
    private function xpath_attr($xp,$queries,$attr){foreach($queries as $q){$n=@$xp->query($q);if($n&&$n->length){$v=trim((string)$n->item(0)->getAttribute($attr));if($v)return $v;}}return '';}
    private function clean_product_name($name){$name=$this->clean_text($name);$name=preg_replace('/\s*(?:Chọn một tùy chọn|Mở sản phẩm|Xem sản phẩm|Mua ngay).*$/iu','',$name);$name=preg_replace('/\s*(?:Khoảng giá|Giá):.*$/iu','',$name);return trim($name);}
    private function pick_image_from_node($xp,$node,$base){$candidates=[];foreach(@$xp->query('.//img',$node) as $im){$attrs=[];foreach(['data-large_image','data-src','data-lazy-src','src'] as $a){$v=trim($im->getAttribute($a));if($v)$attrs[]=$v;}if($im->hasAttribute('srcset')){$parts=preg_split('/\s*,\s*/',$im->getAttribute('srcset'));if(!empty($parts)){$last=trim($parts[count($parts)-1]);$last=preg_replace('/\s+\d+[wx]$/i','',$last);if($last)$attrs[]=$last;}}foreach($attrs as $raw){$u=$this->abs_url($raw,$base);if(!$u||!preg_match('#^https?://#i',$u))continue;$low=strtolower($u.' '.$im->getAttribute('class').' '.$im->getAttribute('alt'));if(preg_match('/logo|favicon|icon|avatar|placeholder|spacer|banner|header|footer/i',$low))continue;$score=0;if(strpos($low,'product')!==false)$score+=5;if(strpos($low,'woocommerce')!==false)$score+=3;if(strpos($low,'thumbnail')!==false)$score+=2;if(strpos($low,'wp-content/uploads')!==false)$score+=2;$candidates[$u]=max($candidates[$u]??0,$score);}}if(!$candidates)return '';arsort($candidates);return (string)array_key_first($candidates);}
    private function parse_listing($html,$source_url){$d=$this->dom($html);if(!$d)return[];$xp=new DOMXPath($d);$out=[];$seen=[];$host=wp_parse_url($source_url,PHP_URL_HOST);$nodes=@$xp->query('//li[contains(concat(" ",normalize-space(@class)," ")," product ")]');if(!$nodes||!$nodes->length)$nodes=@$xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," product-small ")]');if(!$nodes||!$nodes->length)$nodes=@$xp->query('//*[contains(@class,"product") and (.//h2 or .//h3 or .//img)]');foreach($nodes as $node){$a=null;foreach(@$xp->query('.//a[@href]',$node) as $aa){$href=$this->abs_url($aa->getAttribute('href'),$source_url);if($href&&$this->same_host($href,$host)&&$this->looks_like_product_url($href,$source_url)){$a=$aa;break;}}if(!$a)continue;$url=$this->normalize_url($this->abs_url($a->getAttribute('href'),$source_url));if(isset($seen[$url]))continue;$name=$this->xpath_text($xp,['.//*[contains(concat(" ",normalize-space(@class)," ")," woocommerce-loop-product__title ")]','.//*[contains(concat(" ",normalize-space(@class)," ")," product-title ")]','.//h2','.//h3','.//h4']);if(!$name)$name=$a->getAttribute('title');if(!$name){foreach(@$xp->query('.//img[@alt]',$node) as $im){$alt=$this->clean_product_name($im->getAttribute('alt'));if($alt&&!preg_match('/logo|icon|banner/i',$alt)){$name=$alt;break;}}}$name=$this->clean_product_name($name);$price=$this->xpath_text($xp,['.//*[contains(concat(" ",normalize-space(@class)," ")," price ")]','.//*[contains(@class,"woocommerce-Price-amount")]']);$img=$this->pick_image_from_node($xp,$node,$source_url);$has=(bool)@$xp->query('.//*[contains(@class,"variation") or contains(@class,"variable") or contains(@class,"variations_form") or contains(@class,"options")]',$node)->length;if(!$name)continue;$seen[$url]=1;$out[]=['url'=>$url,'name'=>$name,'image'=>$img,'price'=>$this->clean_text($price),'has_variations'=>$has];}return$out;}
    private function same_host($url,$host){$h=wp_parse_url($url,PHP_URL_HOST);return$h&&$host&&(strcasecmp($h,$host)===0||strcasecmp(preg_replace('/^www\./i','',$h),preg_replace('/^www\./i','',$host))===0);}
    private function looks_like_product_url($url,$source_url){if(!$url||!$this->same_host($url,wp_parse_url($source_url,PHP_URL_HOST)))return false;$path=rtrim((string)wp_parse_url($url,PHP_URL_PATH),'/');if(!$path)return false;if(preg_match('#/(page|feed|author|cart|checkout|my-account|gio-hang|thanh-toan)(?:/|$)#i',$path))return false;if(preg_match('/\.(jpg|jpeg|png|gif|webp|pdf|xml)$/i',$path))return false;if(preg_match('#/muc/san-pham(?:/page/\d+)?/?$#i',$path))return false;return true;}
    private function find_pagination($html,$source_url){$d=$this->dom($html);if(!$d)return[];$xp=new DOMXPath($d);$pages=[];$seen=[];$base=$this->normalize_url($source_url);$pages[]=['url'=>$base,'label'=>'1'];$seen[$base]=1;foreach(@$xp->query('//a[@href]') as $a){$href=$this->abs_url($a->getAttribute('href'),$source_url);if(!$href||!$this->same_host($href,wp_parse_url($source_url,PHP_URL_HOST)))continue;$path=(string)wp_parse_url($href,PHP_URL_PATH);$query=(string)wp_parse_url($href,PHP_URL_QUERY);$label=$this->clean_text($a->textContent);$num=0;if(preg_match('#/page/(\d+)/?$#i',$path,$m))$num=(int)$m[1];elseif(preg_match('/(?:^|&)(?:paged|page)=(\d+)/i',$query,$m))$num=(int)$m[1];elseif(preg_match('/^\d+$/',$label))$num=(int)$label;if($num>1){$u=$this->normalize_url($href);if(!isset($seen[$u])){$seen[$u]=1;$pages[]=['url'=>$u,'label'=>(string)$num];}}}usort($pages,function($a,$b){return(int)$a['label']-(int)$b['label'];});return array_slice($pages,0,50);}
    public function ajax_scan_source(){if(!current_user_can('manage_woocommerce'))wp_send_json_error('Không có quyền.');check_ajax_referer(self::NONCE,'nonce');$source=esc_url_raw(wp_unslash($_POST['source_url']??''));if(!$source)wp_send_json_error('URL không hợp lệ.');$html=$this->get_html($source);if(is_wp_error($html))wp_send_json_error($html->get_error_message());$pages=$this->find_pagination($html,$source);if(empty($_POST['scan_all']))$pages=array_slice($pages,0,1);$products=[];$seen=[];$page_errors=[];foreach($pages as $page){$ph=$page['url']===$this->normalize_url($source)?$html:$this->get_html($page['url']);if(is_wp_error($ph)){$page_errors[]=['page'=>$page['label'],'message'=>$ph->get_error_message()];continue;}foreach($this->parse_listing($ph,$page['url']) as $p){if(isset($seen[$p['url']]))continue;$seen[$p['url']]=1;$products[]=$p;if(count($products)>=300)break 2;}}wp_send_json_success(['products'=>$products,'pages'=>$pages,'page_errors'=>$page_errors]);}
    private function parse_product($url) {
        $html=$this->get_html($url); if(is_wp_error($html)) return $html;
        $d=$this->dom($html); if(!$d) return new WP_Error('dom','PHP DOMDocument chưa bật.');
        $xp=new DOMXPath($d);
        $title=$this->xpath_attr($xp,['//meta[@property="og:title"]','//meta[@name="twitter:title"]'],'content');
        if(!$title)$title=$this->xpath_text($xp,['//h1[contains(@class,"product_title")]','//h1','//title']); $title=$this->clean_product_name($title);
        $short=$this->xpath_text($xp,['//div[contains(@class,"woocommerce-product-details__short-description")]','//div[contains(@class,"short-description")]','//div[contains(@class,"product-short-description")]']);
        $content=$this->xpath_text($xp,['//div[contains(@class,"woocommerce-Tabs-panel--description")]','//div[contains(@class,"product-description")]','//div[contains(@class,"entry-content")]']);
        $sku=$this->xpath_text($xp,['//*[contains(concat(" ",normalize-space(@class)," ")," sku ")]']); $price_text=$this->xpath_text($xp,['//p[contains(concat(" ",normalize-space(@class)," ")," price ")]','//*[contains(concat(" ",normalize-space(@class)," ")," price ")]']);
        $regular=$this->xpath_text($xp,['//*[contains(concat(" ",normalize-space(@class)," ")," regular-price ")]','//del//span[contains(@class,"amount")]','//del']); $sale=$this->xpath_text($xp,['//*[contains(concat(" ",normalize-space(@class)," ")," sale-price ")]','//ins//span[contains(@class,"amount")]','//ins']);
        $json=$this->extract_offer_prices($xp); $regular_price=$this->parse_price($regular?:$price_text); $sale_price=$this->parse_price($sale); if(!$regular_price)$regular_price=$json['regular']; if(!$sale_price)$sale_price=$json['sale']; if(!$regular_price&&$sale_price)$regular_price=$sale_price;
        $images=[]; foreach(@$xp->query('//meta[@property="og:image"] | //meta[@name="twitter:image"]') as $m){$v=$m->getAttribute('content');if($v)$images[]=$this->abs_url($v,$url);} foreach(['//div[contains(@class,"woocommerce-product-gallery")]//img','//div[contains(@class,"product-gallery")]//img','//figure[contains(@class,"woocommerce-product-gallery__image")]//img'] as $q){foreach(@$xp->query($q) as $im){foreach(['data-large_image','data-src','data-lazy-src','src'] as $attr){$v=trim($im->getAttribute($attr));if(!$v)continue;$u=$this->abs_url($v,$url);$low=strtolower($u.' '.$im->getAttribute('class').' '.$im->getAttribute('alt'));if(!preg_match('/logo|favicon|icon|avatar|placeholder|banner|header|footer/i',$low))$images[]=$u;break;}}}$images=array_values(array_unique(array_filter($images)));
        $attribute_map=[];
        foreach(@$xp->query('//form[contains(@class,"variations_form")]//select[contains(@name,"attribute_")] | //select[contains(@name,"attribute_")]') as $sel){$name=trim($sel->getAttribute('name'));if(!$name)continue;$label=$this->clean_text($sel->getAttribute('aria-label'));if(!$label){$for=$sel->getAttribute('id');if($for){$lab=@$xp->query('//label[@for="'.esc_attr($for).'"]');if($lab&&$lab->length)$label=$this->clean_text($lab->item(0)->textContent);}}if(!$label)$label=ucwords(str_replace(['attribute_','_','-'],' ',preg_replace('/^attribute_/','',$name)));$values=[];foreach(@$xp->query('.//option[@value and normalize-space(@value)!=""]',$sel) as $op){$txt=$this->clean_text($op->textContent);$val=trim($op->getAttribute('value'));if($txt&&$val&&stripos($txt,'chọn')===false)$values[$val]=$txt;}if($values)$attribute_map[$name]=['label'=>$label,'values'=>array_values($values)];}
        $variations=[];
        foreach(@$xp->query('//form[contains(@class,"variations_form")]') as $form){$raw=$form->getAttribute('data-product_variations');if(!$raw)continue;$decoded=json_decode(html_entity_decode($raw,ENT_QUOTES,'UTF-8'),true);if(is_array($decoded)){foreach($decoded as $v){if(!is_array($v))continue;$attrs=[];foreach((array)($v['attributes']??[]) as $ak=>$av){$ak=(string)$ak;$av=trim((string)$av);if($av==='')continue;$label=$attribute_map[$ak]['label']??ucwords(str_replace(['attribute_','_','-'],' ',preg_replace('/^attribute_/','',$ak)));$display=$av;if(isset($attribute_map[$ak]['values']))foreach($attribute_map[$ak]['values'] as $val)if(sanitize_title($val)===sanitize_title($av)||strcasecmp($val,$av)===0){$display=$val;break;}$attrs[$label]=$display;}$vr=(float)($v['display_regular_price']??0);$vs=(float)($v['display_price']??0);if(!$vr&&$vs)$vr=$vs;$vi='';if(!empty($v['image']['full_src']))$vi=$this->abs_url($v['image']['full_src'],$url);elseif(!empty($v['image']['src']))$vi=$this->abs_url($v['image']['src'],$url);$variations[]=['id'=>absint($v['variation_id']??0),'attributes'=>$attrs,'regular_price'=>$vr,'sale_price'=>($vs>0&&$vr>0&&$vs<$vr?$vs:0),'image'=>$vi,'sku'=>$this->clean_text($v['sku']??'')];}}}
        if(!$variations&&$attribute_map){$values=[];foreach($attribute_map as $a)$values[]=$a['values'];$combos=[[]];foreach($values as $vals){$next=[];foreach($combos as $combo)foreach($vals as $v)$next[]=array_merge($combo,[$v]);$combos=$next;}foreach($combos as $combo){$attrs=[];$i=0;foreach($attribute_map as $a)$attrs[$a['label']]=$combo[$i++]??'';if($attrs)$variations[]=['id'=>0,'attributes'=>$attrs,'regular_price'=>$regular_price,'sale_price'=>$sale_price,'image'=>'','sku'=>''];}}
        $attributes=[];foreach($attribute_map as $a)$attributes[]=['name'=>$a['label'],'options'=>$a['values']]; $spec='';foreach(@$xp->query('//table') as $table){$txt=$this->clean_text($table->textContent);if(strlen($txt)>20&&strlen($txt)<12000){$spec=$txt;break;}}
        return ['url'=>$url,'title'=>$title,'short_description'=>$short,'content'=>$content,'price_text'=>$price_text,'regular_price'=>$regular_price,'sale_price'=>$sale_price,'sku'=>$this->clean_text($sku),'images'=>$images,'attributes'=>$attributes,'specs'=>$spec,'variations'=>$variations,'has_variations'=>!empty($variations)];
    }
    private function extract_offer_prices($xp){$out=['regular'=>0,'sale'=>0];foreach(@$xp->query('//script[@type="application/ld+json"]') as $s){$json=json_decode(trim($s->textContent),true);if(!is_array($json))continue;$stack=[$json];while($stack){$x=array_pop($stack);if(!is_array($x))continue;if(isset($x['offers']))$stack[]=$x['offers'];if(isset($x['price'])){$v=(float)preg_replace('/[^0-9.]/','',(string)$x['price']);if($v>0)$out['sale']=$out['sale']?:$v;}if(isset($x['lowPrice'])){$v=(float)preg_replace('/[^0-9.]/','',(string)$x['lowPrice']);if($v>0)$out['regular']=$out['regular']?:$v;}foreach($x as $v)if(is_array($v))$stack[]=$v;}}return$out;}
    private function image_id($url,$post_id=0){if(!$url)return 0;require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/image.php';$tmp=download_url($url,30);if(is_wp_error($tmp))return 0;$type=wp_check_filetype(wp_basename(parse_url($url,PHP_URL_PATH)));if(!empty($type['type'])&&strpos($type['type'],'image/')!==0){@unlink($tmp);return 0;}$name=wp_basename(parse_url($url,PHP_URL_PATH));if(!$name||strpos($name,'.')===false)$name='image-'.md5($url).'.jpg';$file=['name'=>sanitize_file_name($name),'tmp_name'=>$tmp];$id=media_handle_sideload($file,$post_id);if(is_wp_error($id)){@unlink($tmp);return 0;}return(int)$id;}
    private function parse_price($txt){$txt=html_entity_decode(wp_strip_all_tags((string)$txt),ENT_QUOTES,'UTF-8');if(preg_match_all('/(\d{1,3}(?:[.,]\d{3})+|\d{4,})(?:\s*(?:₫|đ|vnd|vnđ))?/iu',$txt,$m)){$vals=[];foreach($m[1] as $v){$v=preg_replace('/[^0-9]/','',$v);if($v!=='')$vals[]=(float)$v;}if($vals)return min($vals);}return 0;}
    private function ai_rewrite($data){$o=$this->opts();if(empty($o['api_key']))return new WP_Error('no_key','Chưa có OpenAI API Key.');$prompt="Bạn là chuyên gia SEO cho cửa hàng Xe Đạp Ninh Bình tại Việt Nam.\nHãy viết lại nội dung sản phẩm từ dữ liệu nguồn dưới đây thành nội dung riêng, tự nhiên, không sao chép nguyên văn.\nKhông được bịa thông số, giá, màu sắc hoặc tính năng. Nếu dữ liệu không có thì bỏ qua.\nTên thương hiệu nguồn có thể giữ nguyên khi cần xác định sản phẩm.\nTrả về JSON hợp lệ với các khóa: name, short_description, description, seo_title, meta_description, tags.\ndescription dùng HTML đơn giản gồm h2/h3, p, ul, li.\nTập trung từ khóa: xe đạp Thống Nhất, xe đạp Ninh Bình, mua xe đạp Thống Nhất chính hãng.\nDữ liệu:\n".wp_json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$body=['model'=>$o['model']?:'gpt-5-mini','input'=>$prompt,'text'=>['format'=>['type'=>'json_object']]];$r=wp_remote_post('https://api.openai.com/v1/responses',['timeout'=>90,'headers'=>['Authorization'=>'Bearer '.$o['api_key'],'Content-Type'=>'application/json'],'body'=>wp_json_encode($body)]);if(is_wp_error($r))return$r;$code=wp_remote_retrieve_response_code($r);$raw=wp_remote_retrieve_body($r);$j=json_decode($raw,true);if($code<200||$code>=300){$err=$j['error']['message']??('OpenAI HTTP '.$code);return new WP_Error('openai',$err);}$text='';if(isset($j['output_text']))$text=$j['output_text'];if(!$text&&!empty($j['output']))foreach($j['output'] as $out)foreach(($out['content']??[]) as $c)if(isset($c['text']))$text.=$c['text'];$decoded=json_decode(trim($text),true);if(!is_array($decoded))return new WP_Error('ai_json','AI không trả JSON hợp lệ.');return$decoded;}
    private function product_exists_by_source($url){$q=new WP_Query(['post_type'=>'product','post_status'=>'any','meta_key'=>'_xdn_source_url','meta_value'=>$url,'posts_per_page'=>1,'fields'=>'ids']);return!empty($q->posts)?(int)$q->posts[0]:0;}
    private function create_variable_product($name,$desc,$short,$data,$cat,$ai){$product=new WC_Product_Variable();$product->set_name($name?:'Sản phẩm nhập từ nguồn');$product->set_status('draft');$product->set_description($desc);$product->set_short_description($short);if(!empty($data['sku']))$product->set_sku(sanitize_text_field($data['sku']));$post_id=$product->save();if($cat)wp_set_object_terms($post_id,[$cat],'product_cat');$attrs=[];$attribute_keys=[];foreach((array)($data['attributes']??[]) as $a){$an=sanitize_text_field($a['name']??'');$opts=array_values(array_filter(array_map('sanitize_text_field',(array)($a['options']??[]))));if(!$an||!$opts)continue;$attr=new WC_Product_Attribute();$attr->set_id(0);$attr->set_name($an);$attr->set_options($opts);$attr->set_position(count($attrs));$attr->set_visible(true);$attr->set_variation(true);$attrs[]=$attr;$attribute_keys[$an]=sanitize_title($an);}if($attrs){$product->set_attributes($attrs);$product->save();}$created=0;$gallery=[];foreach((array)($data['variations']??[]) as $v){$va=$v['attributes']??[];if(!$va)continue;$variation=new WC_Product_Variation();$variation->set_parent_id($post_id);$variation->set_status('publish');$mapped=[];foreach($va as $label=>$value){$key=$attribute_keys[$label]??sanitize_title($label);$mapped[$key]=sanitize_title($value);}$variation->set_attributes($mapped);$vr=(float)($v['regular_price']??0);$vs=(float)($v['sale_price']??0);if(!$vr&&$vs)$vr=$vs;if($vr>0)$variation->set_regular_price((string)$vr);if($vs>0&&$vs<$vr)$variation->set_sale_price((string)$vs);if(!empty($v['sku']))$variation->set_sku(sanitize_text_field($v['sku']));$vid=$variation->save();$created++;if(!empty($v['image'])){$iid=$this->image_id($v['image'],$post_id);if($iid){$variation->set_image_id($iid);$variation->save();$gallery[]=$iid;}}}if(!$created)return new WP_Error('no_variations','Đã phát hiện thuộc tính nhưng không tạo được biến thể.');foreach(array_slice($data['images']??[],0,12) as $img){$id=$this->image_id($img,$post_id);if($id)$gallery[]=$id;}$gallery=array_values(array_unique($gallery));if($gallery){set_post_thumbnail($post_id,$gallery[0]);if(count($gallery)>1)update_post_meta($post_id,'_product_image_gallery',implode(',',array_slice($gallery,1)));}if(!empty($ai['tags'])&&is_array($ai['tags']))wp_set_object_terms($post_id,array_map('sanitize_text_field',$ai['tags']),'product_tag');if(!empty($ai['seo_title']))update_post_meta($post_id,'_xdn_seo_title',sanitize_text_field($ai['seo_title']));if(!empty($ai['meta_description']))update_post_meta($post_id,'_xdn_meta_description',sanitize_text_field($ai['meta_description']));update_post_meta($post_id,'_xdn_source_url',$data['url']);update_post_meta($post_id,'_xdn_source_sku',sanitize_text_field($data['sku']??''));update_post_meta($post_id,'_xdn_source_data',wp_json_encode($data,JSON_UNESCAPED_UNICODE));update_post_meta($post_id,'_xdn_import_version',self::VERSION);WC_Product_Variable::sync($post_id);wc_delete_product_transients($post_id);return['id'=>$post_id,'variations'=>$created,'images'=>count($gallery)];}
    private function update_variable_product($post_id,$data,$name,$desc,$short,$ai,$cat){
        $product=wc_get_product($post_id); if(!$product||!($product instanceof WC_Product_Variable)) return new WP_Error('not_variable','Sản phẩm hiện tại không phải sản phẩm có biến thể.');
        $product->set_name($name?:$product->get_name()); $product->set_description($desc); $product->set_short_description($short); if(!empty($data['sku']))$product->set_sku(sanitize_text_field($data['sku'])); $product->save();
        $attrs=[];$attribute_keys=[];foreach((array)($data['attributes']??[]) as $a){$an=sanitize_text_field($a['name']??'');$opts=array_values(array_filter(array_map('sanitize_text_field',(array)($a['options']??[]))));if(!$an||!$opts)continue;$attr=new WC_Product_Attribute();$attr->set_id(0);$attr->set_name($an);$attr->set_options($opts);$attr->set_position(count($attrs));$attr->set_visible(true);$attr->set_variation(true);$attrs[]=$attr;$attribute_keys[$an]=sanitize_title($an);}if($attrs){$product->set_attributes($attrs);$product->save();}
        foreach($product->get_children() as $vid) wp_delete_post($vid,true);
        $created=0;$gallery=[];foreach((array)($data['variations']??[]) as $v){$va=$v['attributes']??[];if(!$va)continue;$variation=new WC_Product_Variation();$variation->set_parent_id($post_id);$variation->set_status('publish');$mapped=[];foreach($va as $label=>$value){$key=$attribute_keys[$label]??sanitize_title($label);$mapped[$key]=sanitize_title($value);}$variation->set_attributes($mapped);$vr=(float)($v['regular_price']??0);$vs=(float)($v['sale_price']??0);if(!$vr&&$vs)$vr=$vs;if($vr>0)$variation->set_regular_price((string)$vr);if($vs>0&&$vs<$vr)$variation->set_sale_price((string)$vs);if(!empty($v['sku']))$variation->set_sku(sanitize_text_field($v['sku']));$vid=$variation->save();$created++;if(!empty($v['image'])){$iid=$this->image_id($v['image'],$post_id);if($iid){$variation->set_image_id($iid);$variation->save();$gallery[]=$iid;}}}
        if(!$created)return new WP_Error('no_variations','Nguồn không còn variation hợp lệ.');foreach(array_slice($data['images']??[],0,12) as $img){$id=$this->image_id($img,$post_id);if($id)$gallery[]=$id;}$gallery=array_values(array_unique($gallery));if($gallery){set_post_thumbnail($post_id,$gallery[0]);if(count($gallery)>1)update_post_meta($post_id,'_product_image_gallery',implode(',',array_slice($gallery,1)));}if($cat)wp_set_object_terms($post_id,[$cat],'product_cat');if(!empty($ai['tags'])&&is_array($ai['tags']))wp_set_object_terms($post_id,array_map('sanitize_text_field',$ai['tags']),'product_tag');if(!empty($ai['seo_title']))update_post_meta($post_id,'_xdn_seo_title',sanitize_text_field($ai['seo_title']));if(!empty($ai['meta_description']))update_post_meta($post_id,'_xdn_meta_description',sanitize_text_field($ai['meta_description']));update_post_meta($post_id,'_xdn_source_data',wp_json_encode($data,JSON_UNESCAPED_UNICODE));update_post_meta($post_id,'_xdn_source_sku',sanitize_text_field($data['sku']??''));update_post_meta($post_id,'_xdn_import_version',self::VERSION);WC_Product_Variable::sync($post_id);wc_delete_product_transients($post_id);return['id'=>$post_id,'variations'=>$created,'images'=>count($gallery)];
    }
    private function xdn_technical_specs_html($data){
        $rows=[];$seen=[];$add=function($label,$value)use(&$rows,&$seen){$label=trim(wp_strip_all_tags((string)$label));$value=trim(wp_strip_all_tags((string)$value));if($label&&$value&&empty($seen[mb_strtolower($label)])){$seen[mb_strtolower($label)]=1;$rows[]='<tr><th scope="row">'.esc_html($label).'</th><td>'.esc_html($value).'</td></tr>';}};
        $add('SKU',$data['sku']??'');
        foreach((array)($data['attributes']??[]) as $a){$name=$a['name']??'';$opts=$a['options']??[];if(is_array($opts))$opts=implode(', ',$opts);$add($name,$opts);}
        if(!empty($data['frame']))$add('Khung xe',$data['frame']); if(!empty($data['fork']))$add('Phuộc',$data['fork']); if(!empty($data['wheel_size']))$add('Kích thước bánh',$data['wheel_size']); if(!empty($data['tire']))$add('Lốp',$data['tire']); if(!empty($data['height']))$add('Chiều cao phù hợp',$data['height']); if(!empty($data['weight']))$add('Trọng lượng',$data['weight']); if(!empty($data['brand']))$add('Thương hiệu',$data['brand']);
        if(empty($rows))return '';
        return '<section class="xdn-technical-specs"><h2>Thông số kỹ thuật</h2><table class="shop_attributes"><tbody>'.implode('',$rows).'</tbody></table></section>';
    }
    private function xdn_internal_links_html($post_id,$cat=0){
        $o=$this->opts();if(empty($o['internal_links'])||empty($o['max_internal_links']))return '';$links=[];$home=home_url('/');$links[]=['Xe Đạp Ninh Bình',$home];if(!$cat){$terms=wp_get_post_terms($post_id,'product_cat',['fields'=>'ids']);if(!is_wp_error($terms)&&!empty($terms))$cat=(int)$terms[0];}if($cat){$term=get_term($cat,'product_cat');if($term&&!is_wp_error($term))$links[]=['Xe đạp '. $term->name,get_term_link($term)];$q=new WP_Query(['post_type'=>'product','post_status'=>'publish','posts_per_page'=>max(1,$o['max_internal_links']-count($links)+1),'post__not_in'=>[$post_id],'tax_query'=>[['taxonomy'=>'product_cat','field'=>'term_id','terms'=>$cat]],'orderby'=>'rand','no_found_rows'=>true,'fields'=>'ids']);foreach($q->posts as $id){$links[]=[get_the_title($id),get_permalink($id)];if(count($links)>$o['max_internal_links'])break;}}
        $links=array_slice($links,0,(int)$o['max_internal_links']);if(!$links)return '';return '<section class="xdn-related-links"><h2>Sản phẩm liên quan</h2><ul>'.implode('',array_map(function($x){return '<li><a href="'.esc_url($x[1]).'">'.esc_html($x[0]).'</a></li>';},$links)).'</ul></section>';
    }
    private function xdn_prepare_content($post_id,$desc,$data,$cat=0){$o=$this->opts();$desc=trim((string)$desc);if(!empty($o['specs_section'])&&!preg_match('/Thông số kỹ thuật/i',$desc))$desc.="\n\n".$this->xdn_technical_specs_html($data);if(!empty($o['internal_links'])&&!preg_match('/xdn-related-links/i',$desc))$desc.="\n\n".$this->xdn_internal_links_html($post_id,$cat);return $desc;}

    public function ajax_update_source(){
        if(!current_user_can('manage_woocommerce'))wp_send_json_error('Không có quyền.');check_ajax_referer(self::NONCE,'nonce');if(!class_exists('WooCommerce'))wp_send_json_error('WooCommerce chưa được kích hoạt.');$post_id=absint($_POST['product_id']??0);$url=esc_url_raw(wp_unslash($_POST['source_url']??''));if(!$post_id||!$url)wp_send_json_error('Thiếu sản phẩm hoặc URL nguồn.');$data=$this->parse_product($url);if(is_wp_error($data))wp_send_json_error($data->get_error_message());$o=$this->opts();$use_ai=!empty($_POST['use_ai']);$ai=[];if($use_ai){$ai=$this->ai_rewrite($data);if(is_wp_error($ai))wp_send_json_error('OpenAI: '.$ai->get_error_message());}$name=sanitize_text_field($ai['name']??$data['title']??'');$desc=wp_kses_post($ai['description']??$data['content']??'');$short=wp_kses_post($ai['short_description']??$data['short_description']??'');$cat=0;$terms=wp_get_post_terms($post_id,'product_cat',['fields'=>'ids']);if(!is_wp_error($terms)&&!empty($terms))$cat=(int)$terms[0];$desc=$this->xdn_prepare_content($post_id,$desc,$data,$cat);$product=wc_get_product($post_id);if(!$product)wp_send_json_error('Không tìm thấy sản phẩm WooCommerce.');try{if($product instanceof WC_Product_Variable && !empty($data['variations'])){$r=$this->update_variable_product($post_id,$data,$name,$desc,$short,$ai,$cat);if(is_wp_error($r))wp_send_json_error($r->get_error_message());$msg='Đã cập nhật nguồn: '.$r['variations'].' biến thể, '.$r['images'].' ảnh.';}else{$regular=(float)($data['regular_price']??0);$sale=(float)($data['sale_price']??0);if($sale>0&&$regular>0&&$sale>=$regular)$sale=0;if(!$regular&&$sale)$regular=$sale;$product->set_name($name?:$product->get_name());$product->set_description($desc);$product->set_short_description($short);if($regular>0)$product->set_regular_price((string)$regular);else $product->set_regular_price('');if($sale>0)$product->set_sale_price((string)$sale);else $product->set_sale_price('');if(!empty($data['sku']))$product->set_sku(sanitize_text_field($data['sku']));$product->save();$gallery=[];foreach(array_slice($data['images']??[],0,12) as $img){$id=$this->image_id($img,$post_id);if($id)$gallery[]=$id;}$gallery=array_values(array_unique($gallery));if($gallery){set_post_thumbnail($post_id,$gallery[0]);if(count($gallery)>1)update_post_meta($post_id,'_product_image_gallery',implode(',',array_slice($gallery,1)));}if(!empty($ai['tags'])&&is_array($ai['tags']))wp_set_object_terms($post_id,array_map('sanitize_text_field',$ai['tags']),'product_tag');if(!empty($ai['seo_title']))update_post_meta($post_id,'_xdn_seo_title',sanitize_text_field($ai['seo_title']));if(!empty($ai['meta_description']))update_post_meta($post_id,'_xdn_meta_description',sanitize_text_field($ai['meta_description']));$msg='Đã cập nhật nguồn: '.count($gallery).' ảnh.';}}
        update_post_meta($post_id,'_xdn_source_url',$url);update_post_meta($post_id,'_xdn_source_data',wp_json_encode($data,JSON_UNESCAPED_UNICODE));update_post_meta($post_id,'_xdn_source_sku',sanitize_text_field($data['sku']??''));update_post_meta($post_id,'_xdn_import_version',self::VERSION);wp_send_json_success(['id'=>$post_id,'message'=>$msg]);
    }

    public function ajax_import_products(){if(!current_user_can('manage_woocommerce'))wp_send_json_error('Không có quyền.');check_ajax_referer(self::NONCE,'nonce');if(!class_exists('WooCommerce'))wp_send_json_error('WooCommerce chưa được kích hoạt.');$products=json_decode(wp_unslash($_POST['products']??'[]'),true);$cat=absint($_POST['category']??0);$use_ai=!empty($_POST['use_ai']);$results=[];foreach((array)$products as $p){$url=esc_url_raw($p['url']??'');if(!$url){$results[]=['status'=>'error','message'=>'URL trống'];continue;}if($existing=$this->product_exists_by_source($url)){$results[]=['status'=>'exists','id'=>$existing,'edit_url'=>get_edit_post_link($existing,'',''), 'message'=>'Đã tồn tại sản phẩm WooCommerce #'.$existing.' (trùng URL nguồn).'];continue;}$data=$this->parse_product($url);if(is_wp_error($data)){$results[]=['status'=>'error','message'=>$data->get_error_message()];continue;}$ai=[];if($use_ai){$ai=$this->ai_rewrite($data);if(is_wp_error($ai)){$results[]=['status'=>'error','message'=>'OpenAI: '.$ai->get_error_message()];continue;}}$name=sanitize_text_field($ai['name']??$data['title']??$p['name']);$desc=wp_kses_post($ai['description']??$data['content']??'');$short=wp_kses_post($ai['short_description']??$data['short_description']??'');$desc=$this->xdn_prepare_content(0,$desc,$data,$cat);try{if(!empty($data['has_variations'])&&!empty($data['variations'])){$r=$this->create_variable_product($name,$desc,$short,$data,$cat,$ai);if(is_wp_error($r))throw new Exception($r->get_error_message());$results[]=['status'=>'created','id'=>$r['id'],'message'=>'Đã tạo sản phẩm biến thể nháp #'.$r['id'].' ('.$r['variations'].' biến thể)','name'=>$name,'variations'=>$r['variations'],'images'=>$r['images']];continue;}$regular=(float)($data['regular_price']??0);$sale=(float)($data['sale_price']??0);if($sale>0&&$regular>0&&$sale>=$regular)$sale=0;if(!$regular&&$sale)$regular=$sale;$product=new WC_Product_Simple();$product->set_name($name?:'Sản phẩm nhập từ nguồn');$product->set_status('draft');$product->set_description($desc);$product->set_short_description($short);if($regular>0)$product->set_regular_price((string)$regular);if($sale>0)$product->set_sale_price((string)$sale);if(!empty($data['sku']))$product->set_sku(sanitize_text_field($data['sku']));$post_id=$product->save();}catch(Exception $e){$results[]=['status'=>'error','message'=>$e->getMessage()];continue;}update_post_meta($post_id,'_xdn_source_url',$url);update_post_meta($post_id,'_xdn_source_sku',sanitize_text_field($data['sku']??''));update_post_meta($post_id,'_xdn_source_data',wp_json_encode($data,JSON_UNESCAPED_UNICODE));update_post_meta($post_id,'_xdn_import_version',self::VERSION);if($cat)wp_set_object_terms($post_id,[$cat],'product_cat');if(!empty($ai['tags'])&&is_array($ai['tags']))wp_set_object_terms($post_id,array_map('sanitize_text_field',$ai['tags']),'product_tag');if(!empty($ai['seo_title']))update_post_meta($post_id,'_xdn_seo_title',sanitize_text_field($ai['seo_title']));if(!empty($ai['meta_description']))update_post_meta($post_id,'_xdn_meta_description',sanitize_text_field($ai['meta_description']));$gallery=[];foreach(array_slice($data['images']??[],0,12) as $img){$id=$this->image_id($img,$post_id);if($id)$gallery[]=$id;}$gallery=array_values(array_unique($gallery));if($gallery){set_post_thumbnail($post_id,$gallery[0]);if(count($gallery)>1)update_post_meta($post_id,'_product_image_gallery',implode(',',$gallery));}$results[]=['status'=>'created','id'=>$post_id,'message'=>'Đã tạo sản phẩm nháp #'.$post_id,'name'=>$name,'regular_price'=>$regular,'sale_price'=>$sale,'images'=>count($gallery)];}wp_send_json_success(['results'=>$results]);}
}
